"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import { BarChart3, Home, Zap, LineChart, Menu, X } from "lucide-react"
import { useState } from "react"

const navItems = [
  {
    label: "Dashboard",
    href: "/",
    icon: Home,
  },
  {
    label: "Prediction",
    href: "/predict",
    icon: Zap,
  },
  {
    label: "Analytics",
    href: "/analytics",
    icon: LineChart,
  },
]

export default function Navigation() {
  const pathname = usePathname()
  const [isOpen, setIsOpen] = useState(false)

  return (
    <nav className="sticky top-0 z-50 bg-slate-900 bg-opacity-80 backdrop-blur-md border-b border-blue-400 border-opacity-20">
      <div className="max-w-7xl mx-auto px-6 py-4">
        <div className="flex justify-between items-center">
          
          <Link href="/" className="flex items-center gap-3 group">
            <div className="p-2 bg-blue-600 rounded-lg group-hover:bg-blue-700 transition">
              <BarChart3 className="w-6 h-6 text-white" />
            </div>
            <div className="hidden sm:block">
              <h1 className="text-white font-bold text-lg">Weather app</h1>
              <p className="text-blue-300 text-xs">Demand Prediction</p>
            </div>
          </Link>

          
          <div className="hidden md:flex items-center gap-8">
            {navItems.map((item) => {
              const Icon = item.icon
              const isActive = pathname === item.href
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg transition font-medium ${
                    isActive ? "bg-blue-600 text-white" : "text-blue-200 hover:bg-blue-600 hover:bg-opacity-20"
                  }`}
                >
                  <Icon className="w-4 h-4" />
                  {item.label}
                </Link>
              )
            })}
          </div>

          <button
            onClick={() => setIsOpen(!isOpen)}
            className="md:hidden p-2 hover:bg-blue-600 hover:bg-opacity-20 rounded-lg transition text-blue-200"
          >
            {isOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </div>

        {isOpen && (
          <div className="md:hidden mt-4 space-y-2 pb-4">
            {navItems.map((item) => {
              const Icon = item.icon
              const isActive = pathname === item.href
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  onClick={() => setIsOpen(false)}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg transition font-medium ${
                    isActive ? "bg-blue-600 text-white" : "text-blue-200 hover:bg-blue-600 hover:bg-opacity-20"
                  }`}
                >
                  <Icon className="w-4 h-4" />
                  {item.label}
                </Link>
              )
            })}
          </div>
        )}
      </div>
    </nav>
  )
}
